def guess_number(n, pick):
    def guess(num):
        if num > pick:
            return -1
        if num < pick:
            return 1
        return 0

    lo, hi = 1, n

    while lo <= hi:
        mid = lo + (hi - lo) // 2
        result = guess(mid)
        if result == 0:
            return mid
        if result < 0:
            hi = mid - 1
        else:
            lo = mid + 1

    return -1

